/**
 * Generates `src/common/intl/locales.generated.ts` from the Twosky language
 * list in `.twosky.json` (project: `home_v2`).
 *
 * Usage:
 *   node ./scripts/generate-locales.js      # regenerate the files
 *   npm run locales:generate               # same, via package.json
 *
 * CI freshness guard:
 *   npm run locales:check                  # fails if output is stale
 *
 * The generated file contains static import statements and a LOCALES map so
 * that webpack can tree-shake each locale JSON bundle.  Every locale from
 * `.twosky.json` → `home_v2.languages` is included except those listed in
 * EXCLUDES below.
 *
 * It also generates loaders for the blocked-service group names, which are
 * owned and translated by Hostlists Registry (`.twosky.json` project
 * `hostlists-registry`) and downloaded into `src/__locales-services/`, plus a
 * second file, `src/common/intl/services.groups.generated.ts`, that maps a
 * group ID to a thunk calling `intl.getMessage()` with a string literal.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

// --- Configuration ---

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..', '..');
const TWOSKY_PATH = resolve(REPO_ROOT, '.twosky.json');

// Allow the caller to override the output paths via `--out <path>` and
// `--out-services <path>`.  Useful for CI checks that want to generate to
// temp files.
const args = process.argv.slice(2);
const outFlagIdx = args.indexOf('--out');
const OUTPUT_PATH =
    outFlagIdx !== -1 && args[outFlagIdx + 1]
        ? resolve(args[outFlagIdx + 1])
        : resolve(__dirname, '..', 'src', 'common', 'intl', 'locales.generated.ts');

const outServicesFlagIdx = args.indexOf('--out-services');
const SERVICES_GROUPS_OUTPUT_PATH =
    outServicesFlagIdx !== -1 && args[outServicesFlagIdx + 1]
        ? resolve(args[outServicesFlagIdx + 1])
        : resolve(__dirname, '..', 'src', 'common', 'intl', 'services.groups.generated.ts');

// --- Helpers ---

/** Turn a hyphenated locale code into a valid JavaScript identifier.
 *  E.g. "pt-br" → "ptBr",  "zh-hk" → "zhHk",  "sr-cs" → "srCs".
 */
const toAlias = (code) => code.replace(/-([a-z])/g, (_, c) => c.toUpperCase());

/** Formats a locale code as an object key, quoting only when required. */
const toObjectKey = (code) =>
    /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(code) ? code : `'${code}'`;

// --- Main ---

try {
    const twoskyRaw = readFileSync(TWOSKY_PATH, 'utf-8');
    const twosky = JSON.parse(twoskyRaw);

    const homeV2 = twosky.find((p) => p.project_id === 'home_v2');
    if (!homeV2) {
        console.error('ERROR: no project with project_id "home_v2" found in .twosky.json');
        process.exit(1);
    }

    const servicesProject = twosky.find((p) => p.project_id === 'hostlists-registry');
    if (!servicesProject) {
        console.error(
            'ERROR: no project with project_id "hostlists-registry" found in .twosky.json',
        );
        process.exit(1);
    }

    const allCodes = Object.keys(homeV2.languages);
    // Stable sort for deterministic output
    allCodes.sort();

    // Verify every locale JSON file exists before writing output
    const localesDir = resolve(__dirname, '..', 'src', '__locales');
    const servicesLocalesDir = resolve(__dirname, '..', 'src', '__locales-services');
    for (const code of allCodes) {
        for (const dir of [localesDir, servicesLocalesDir]) {
            const jsonPath = resolve(dir, `${code}.json`);
            try {
                readFileSync(jsonPath);
            } catch {
                console.error(
                    `ERROR: locale JSON file not found: ${jsonPath}` +
                        `\n  Ensure the file was downloaded from Twosky before regenerating.`,
                );
                process.exit(1);
            }
        }
    }

    // --- Emit ---

    const baseLocale = homeV2.base_locale || 'en';
    const lazyCodes = allCodes.filter((code) => code !== baseLocale);

    const servicesBase = JSON.parse(
        readFileSync(resolve(servicesLocalesDir, `${baseLocale}.json`), 'utf-8'),
    );
    const serviceGroupEntries = Object.keys(servicesBase)
        .map((key) => {
            const match = /^servicesgroup\.(.+)\.name$/.exec(key);

            return match ? [match[1], key] : null;
        })
        .filter(Boolean)
        .sort(([left], [right]) => left.localeCompare(right));

    if (serviceGroupEntries.length === 0) {
        console.error(
            `ERROR: no "servicesgroup.*.name" keys found in ` +
                `${resolve(servicesLocalesDir, `${baseLocale}.json`)}`,
        );
        process.exit(1);
    }

    const lines = [
        '/* eslint-disable */',
        '// AUTO-GENERATED by `npm run locales:generate`.  Do not edit by hand.',
        '// Source: .twosky.json → project_id: home_v2 → languages',
        `// Blocked-services source: .twosky.json → project_id: ${servicesProject.project_id}`,
        '// Excludes: (none)',
        '',
        'export type LocaleMessage = Record<string, string>;',
        '',
        'export type ServicesMessage = Record<string, string | { message: string }>;',
        '',
    ];

    // Static import for the base locale (always bundled, synchronous fallback)
    const baseAlias = toAlias(baseLocale);
    lines.push(`import ${baseAlias} from 'panel/__locales/${baseLocale}.json';`);
    lines.push(
        `import services${baseAlias[0].toUpperCase()}${baseAlias.slice(1)} from 'panel/__locales-services/${baseLocale}.json';`,
    );
    lines.push('');

    // Lazy-loaders for every non-base locale.
    // Return type is Promise<any> because JSON dynamic imports produce
    // { default: LocaleMessage }; the preloadLocale() helper unwraps
    // the .default at runtime.
    lines.push('export const LOCALE_LOADERS: Record<string, () => Promise<any>> = {');
    for (let i = 0; i < lazyCodes.length; i++) {
        const code = lazyCodes[i];
        const comma = i === lazyCodes.length - 1 ? '' : ',';
        lines.push(
            `    ${toObjectKey(code)}: () => import(/* webpackChunkName: "locale.${code}" */ 'panel/__locales/${code}.json')${comma}`,
        );
    }
    lines.push('};');
    lines.push('');

    // All known locale codes (used by resolveLanguage to validate codes
    // before messages are loaded)
    const codeList = allCodes.map((c) => `'${c}'`).join(', ');
    lines.push(`export const LOCALE_CODES = new Set([${codeList}]);`);
    lines.push('');

    // Synchronously available locale data — starts with only the base
    // locale, expanded by preloadLocale() at runtime.
    lines.push('export const LOCALES: Record<string, LocaleMessage> = {');
    lines.push(`    ${baseLocale}: ${baseAlias},`);
    lines.push('};');
    lines.push('');

    // Static import for the base blocked-services locale.
    lines.push(`export const SERVICES_BASE_LOCALE: ServicesMessage = services${baseAlias[0].toUpperCase()}${baseAlias.slice(1)};`);
    lines.push('');

    // Lazy-loaders for the blocked-services group names.  These are a separate
    // Twosky project (hostlists-registry) and a separate JSON file per locale.
    lines.push('export const SERVICES_LOCALE_LOADERS: Record<string, () => Promise<any>> = {');
    for (let i = 0; i < lazyCodes.length; i++) {
        const code = lazyCodes[i];
        const comma = i === lazyCodes.length - 1 ? '' : ',';
        lines.push(
            `    ${toObjectKey(code)}: () => import(/* webpackChunkName: "services-locale.${code}" */ 'panel/__locales-services/${code}.json')${comma}`,
        );
    }
    lines.push('};');
    lines.push('');

    writeFileSync(OUTPUT_PATH, lines.join('\n').trimEnd() + '\n', 'utf-8');

    // The group-name map lives in its own file: it imports the translator, and
    // `panel/common/intl` imports this file, so emitting it here would create a
    // cycle.  Each entry calls getMessage() with a literal, which is what the
    // translation audit detects — a lookup table of bare keys would not be.
    const servicesLines = [
        '/* eslint-disable */',
        '// AUTO-GENERATED by `npm run locales:generate`.  Do not edit by hand.',
        `// Source: .twosky.json → project_id: ${servicesProject.project_id}`,
        '',
        "import intl from 'panel/common/intl';",
        '',
        'export const SERVICE_GROUP_MESSAGES: Record<string, () => string> = {',
    ];
    for (const [id, key] of serviceGroupEntries) {
        servicesLines.push(`    ${toObjectKey(id)}: () => intl.getMessage('${key}'),`);
    }
    servicesLines.push('};');
    servicesLines.push('');

    writeFileSync(
        SERVICES_GROUPS_OUTPUT_PATH,
        servicesLines.join('\n').trimEnd() + '\n',
        'utf-8',
    );

    console.log(`Wrote ${OUTPUT_PATH} (${allCodes.length} locales)`);
    console.log(`Wrote ${SERVICES_GROUPS_OUTPUT_PATH} (${serviceGroupEntries.length} groups)`);
} catch (err) {
    console.error('Failed to generate locales.generated.ts:', err.message);
    process.exit(1);
}
